&lt;ul style=&quot;margin-top:2px&quot;&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste-Des-Marais-(Alchimiste).html&quot; title=&quot;Alchimiste des marais&quot;&gt;Alchimiste des marais&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Grippli-(Race).html&quot; title=&quot;Les gripplis&quot;&gt;Grippli&lt;/a&gt;) (MR)&lt;/li&gt;
