  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chercheur-Dœnopion-(Alchimiste).html&quot; title=&quot;Chercheur visionnaire&quot;&gt;Chercheur visionnaire&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chimiste-Enrag&#233;-(Alchimiste).html&quot; title=&quot;Chimiste enrag&#233;&quot;&gt;Chimiste enrag&#233;&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chimiste-Inspir&#233;-(Alchimiste).html&quot; title=&quot;Chimiste inspir&#233;&quot;&gt;Chimiste inspir&#233;&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chimiste-Spirituel-(Alchimiste).html&quot; title=&quot;Chimiste spirituel&quot;&gt;Chimiste spirituel&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chirurgien-(Alchimiste).html&quot; title=&quot;Chirurgien&quot;&gt;Chirurgien&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Collectionneur-(Alchimiste).html&quot; title=&quot;Collectionneur&quot;&gt;Collectionneur&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ectochimiste-(Alchimiste).html&quot; title=&quot;Ectochimiste&quot;&gt;Ectochimiste&lt;/a&gt; (AO)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Explorateur-De-Cryptes-(Alchimiste).html&quot; title=&quot;Explorateur de cryptes&quot;&gt;Explorateur de cryptes&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Grenadier-(Alchimiste).html&quot; title=&quot;Grenadier&quot;&gt;Grenadier&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Hobgobelin-(Race).html&quot; title=&quot;Les hobgobelins&quot;&gt;Hobgobelin&lt;/a&gt;) (CM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Homonculiste-(Alchimiste).html&quot; title=&quot;Homonculiste &quot;&gt;Homonculiste&lt;/a&gt; (FF)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Interrogateur-(Alchimiste).html&quot; title=&quot;Interrogateur&quot;&gt;Interrogateur&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Inventeur-Alchimiste-(Alchimiste).html&quot; title=&quot;Inventeur alchimiste&quot;&gt;Inventeur alchimiste&lt;/a&gt; (AO)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-Des-Clones-(Alchimiste).html&quot; title=&quot;Ma&#238;tre des clones&quot;&gt;Ma&#238;tre des clones&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Maraudeur-Ail&#233;-(Alchimiste).html&quot; title=&quot;Maraudeur ail&#233;&quot;&gt;Maraudeur ail&#233;&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Gobelin-(Race).html&quot; title=&quot;Les gobelins&quot;&gt;Gobelin&lt;/a&gt;) (CM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;M&#233;tamorphe-(Alchimiste).html&quot; title=&quot;M&#233;tamorphe&quot;&gt;M&#233;tamorphe&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Porte-Peste-(Alchimiste).html&quot; title=&quot;Porte-peste&quot;&gt;Porte-peste&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Homme-Rat-(Race).html&quot; title=&quot;Les hommes-rats&quot;&gt;Homme-rat&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Psychonaute-(Alchimiste).html&quot; title=&quot;Psychonaute&quot;&gt;Psychonaute&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pyrobombardier-(Alchimiste).html&quot; title=&quot;Pyrobombardier&quot;&gt;Pyrobombardier&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Gobelin-(Race).html&quot; title=&quot;Les gobelins&quot;&gt;Gobelin&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#233;animateur-(Alchimiste).html&quot; title=&quot;R&#233;animateur&quot;&gt;R&#233;animateur&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Saboteur-(Alchimiste).html&quot; title=&quot;Saboteur&quot;&gt;Saboteur&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Gnome.html&quot; title=&quot;Les gnomes&quot;&gt;Gnome&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sapeur-Alchimique-(Alchimiste).html&quot; title=&quot;Sapeur alchimique&quot;&gt;Sapeur alchimique&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Trappeur-Alchimique-(Alchimiste).html&quot; title=&quot;Trappeur alchimique&quot;&gt;Trappeur alchimique&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Kobold-(Race).html&quot; title=&quot;Les kobolds&quot;&gt;Kobold&lt;/a&gt;) (CM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Vivisectioniste-(Alchimiste).html&quot; title=&quot;Vivisectioniste&quot;&gt;Vivisectioniste&lt;/a&gt; (AM)&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;script&gt;
$(function () {
  let image = &quot;Illustrations/PNJ/Demi-elfe.jpg&quot;;
  if(image == &quot;&quot; || image == &quot; &quot;) { $(&#39;.symbole2&#39;).html(&quot;&quot;); }
});
&lt;/script&gt;
&lt;div class=&quot;presentation navmenudroite&quot; style=&quot;margin-bottom:5px&quot;&gt;
&lt;table width=&quot;80px&quot;&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;
&lt;td class=&quot;symbole2&quot;&gt;&lt;abbr title=&quot;Cette option est plus sp&#233;cifique, voire r&#233;serv&#233;e, aux membres de la race indiqu&#233;e. Discutez avec votre MJ de sa disponibilit&#233; pour votre personnage.&quot;&gt;&lt;a href=&quot;./Pathfinder-RPG.Demi-elfe.ashx&quot;&gt;&lt;img src=&quot;/wiki/public/upload/Illustrations/PNJ/Demi-elfe.jpg&quot; width=&quot;80%&quot; style=&quot;float:center; margin: 0px -50px 0px 7px; border: 1px solid #4b3124&quot;&gt;&lt;/a&gt;&lt;/abbr&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;
&lt;td&gt;&lt;div style=&quot;text-align:center; font-size: 81%; font-weight: bold;&quot;&gt;Option plus&lt;br /&gt;commune chez&lt;br /&gt;les &lt;a class=&quot;pagelink&quot; href=&quot;Demi-Elfe.html&quot; title=&quot;Les demi-elfes&quot;&gt;demi-elfes&lt;/a&gt;.&lt;/div&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;/table&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des races (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Race Guide, Elves of Golarion, Gnomes of Golarion, Goblins of Golarion, Halflings of Golarion, Humans of Golarion, Dwarves of Golarion, Orcs of Golarion/Manuel des races&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoMR.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;
&lt;i&gt;Certains demi-elfes alchimistes m&#234;lent leur curiosit&#233; humaine &#224; leur affinit&#233; elfique avec la nature. Ils manipulent l’alchimie pour cr&#233;er des bombes capables de remodeler un environnement et de d&#233;sherber des zones de v&#233;g&#233;tation enti&#232;res ou cr&#233;ent des mutag&#232;nes qui permettent d’obtenir la r&#233;sistance du ch&#234;ne ou la t&#233;nacit&#233; du bambou.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Bombes du roncier (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Bombes_du_roncier_Sur_0&quot; href=&quot;#Bombes_du_roncier_Sur_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt; 
&#192; partir du niveau 2, le brasseur d’&#233;pines fait la d&#233;couverte &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;couvertes.html#BOMBEIMMOBILISANTE&quot; title=&quot;Les d&#233;couvertes d&amp;#39;alchimiste&quot;&gt;bombe immobilisante&lt;/a&gt;, mais la dur&#233;e d’immobilisation se poursuit pendant un nombre de &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt; &#233;gal au modificateur d’&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt; du brasseur (1 round au minimum). De plus, quand il lance une bombe immobilisante, elle transforme toutes les cases pr&#233;sentes dans son rayon d’aspersion en &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;placement-Et-Position#Terraindifficile.html&quot; title=&quot;terrain difficile&quot;&gt;terrain difficile&lt;/a&gt;, aussi longtemps que la bombe fait effet. Ces bombes ne font pas de d&#233;g&#226;ts, mais leur rayon d’aspersion augmente de 1,50 m (1 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;) par tranche de 1d6 points de d&#233;g&#226;ts que le brasseur inflige avec ses autres bombes. Ce pouvoir remplace la &lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html#DECOUVERTES&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;d&#233;couverte&lt;/a&gt; de niveau 2.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Mutag&#232;ne de la dendrite (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Mutag&#232;ne_de_la_dendrite_Sur_1&quot; href=&quot;#Mutag&#232;ne_de_la_dendrite_Sur_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 1, le &lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html#MUTAGENES&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;mutag&#232;ne&lt;/a&gt; du brasseur d’&#233;pines rec&#232;le un pouvoir de transformation, mais donne la robustesse des arbres plut&#244;t que la puissance animale des mutag&#232;nes standard. Quand il boit ce mutag&#232;ne, le brasseur gagne un bonus d’armure naturelle de +4 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt;, un bonus alchimique de +2 &#224; une valeur de caract&#233;ristique physique (&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Force.html&quot; title=&quot;La Force&quot;&gt;Force&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Constitution.html&quot; title=&quot;La Constitution&quot;&gt;Constitution&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Dexterite.html&quot; title=&quot;La Dext&#233;rit&#233;&quot;&gt;Dext&#233;rit&#233;&lt;/a&gt;) et un malus de -2 &#224; la caract&#233;ristique mentale correspondante (comme avec le pouvoir de mutag&#232;ne ordinaire). &lt;br /&gt;&lt;br /&gt;De plus, l’alchimiste gagne &lt;a class=&quot;pagelink&quot; href=&quot;Gu&#233;rison-Acc&#233;l&#233;r&#233;e-(Capacit&#233;).html&quot; title=&quot;gu&#233;rison acc&#233;l&#233;r&#233;e&quot;&gt;gu&#233;rison acc&#233;l&#233;r&#233;e&lt;/a&gt; 1 tant qu’il se trouve dans une zone de vive lumi&#232;re (sous les rayons du soleil ou dans une zone de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lumi&#232;re-Du-Jour.html&quot; title=&quot;Lumi&#232;re du jour&quot;&gt;lumi&#232;re du jour&lt;/a&gt;&lt;/i&gt;, par exemple). En dehors de cela, ce pouvoir fonctionne comme le pouvoir de &lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html#MUTAGENES&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;mutag&#232;ne&lt;/a&gt; standard et le remplace.&lt;br /&gt;&lt;br /&gt;Un brasseur d’&#233;pines qui choisit la d&#233;couverte &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;couvertes.html#MUTAGENESUPERIEUR&quot; title=&quot;Les d&#233;couvertes d&amp;#39;alchimiste&quot;&gt;mutag&#232;ne sup&#233;rieur&lt;/a&gt; cr&#233;e un mutag&#232;ne de dendrite qui donne toujours un bonus d’armure naturelle de +4 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt;, mais aussi un bonus alchimique de +4 &#224; une premi&#232;re valeur de caract&#233;ristique physique et de +2 &#224; une deuxi&#232;me. Tant que le mutag&#232;ne fait effet, le brasseur subit un malus de -2 aux deux valeurs de caract&#233;ristique mentales associ&#233;es. Sa gu&#233;rison acc&#233;l&#233;r&#233;e passe &#224; 3 tant qu’il se trouve dans une zone de vive lumi&#232;re. En dehors de cela, ce pouvoir fonctionne comme la d&#233;couverte &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;couvertes.html#MUTAGENESUPERIEUR&quot; title=&quot;Les d&#233;couvertes d&amp;#39;alchimiste&quot;&gt;mutag&#232;ne sup&#233;rieur&lt;/a&gt; et la remplace.&lt;br /&gt;&lt;br /&gt;Un brasseur d’&#233;pines qui choisit la d&#233;couverte &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;couvertes.html#GRANDMUTAGENE&quot; title=&quot;Les d&#233;couvertes d&amp;#39;alchimiste&quot;&gt;grand mutag&#232;ne&lt;/a&gt; cr&#233;e un mutag&#232;ne de dendrite qui donne un bonus d’armure naturelle de +6 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt;, un bonus alchimique de +6 &#224; une premi&#232;re valeur de caract&#233;ristique physique, de +4 &#224; une deuxi&#232;me et de +2 &#224; une troisi&#232;me. Tant que le mutag&#232;ne fait effet, le brasseur subit un malus de -2 &#224; l’&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt;, la &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Sagesse.html&quot; title=&quot;La Sagesse&quot;&gt;Sagesse&lt;/a&gt; et au &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt;. Sa &lt;a class=&quot;pagelink&quot; href=&quot;Gu&#233;rison-Acc&#233;l&#233;r&#233;e-(Capacit&#233;).html&quot; title=&quot;gu&#233;rison acc&#233;l&#233;r&#233;e&quot;&gt;gu&#233;rison acc&#233;l&#233;r&#233;e&lt;/a&gt; passe &#224; 5 tant qu’il se trouve dans une zone de vive lumi&#232;re. En dehors de cela, ce pouvoir fonctionne comme la d&#233;couverte &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;couvertes.html#GRANDMUTAGENE&quot; title=&quot;Les d&#233;couvertes d&amp;#39;alchimiste&quot;&gt;grand mutag&#232;ne&lt;/a&gt; et la remplace.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Grande d&#233;couverte (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Grande_d&#233;couverte_Sur_2&quot; href=&quot;#Grande_d&#233;couverte_Sur_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 20, le brasseur d’&#233;pines qui choisit la grande d&#233;couverte &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;couvertes.html#MUTAGENEABSOLU&quot; title=&quot;Les d&#233;couvertes d&amp;#39;alchimiste&quot;&gt;mutag&#232;ne absolu&lt;/a&gt; cr&#233;e un mutag&#232;ne de dendrite qui donne un bonus d’armure naturelle de +8 et un bonus alchimique de +6 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Force.html&quot; title=&quot;La Force&quot;&gt;Force&lt;/a&gt;, la &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Constitution.html&quot; title=&quot;La Constitution&quot;&gt;Constitution&lt;/a&gt; et &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Dexterite.html&quot; title=&quot;La Dext&#233;rit&#233;&quot;&gt;Dext&#233;rit&#233;&lt;/a&gt;. Tant que le mutag&#232;ne fait effet, le brasseur subit un malus de -2 &#224; l’&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt;, la &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Sagesse.html&quot; title=&quot;La Sagesse&quot;&gt;Sagesse&lt;/a&gt; et au &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt;. Sa &lt;a class=&quot;pagelink&quot; href=&quot;Gu&#233;rison-Acc&#233;l&#233;r&#233;e-(Capacit&#233;).html&quot; title=&quot;gu&#233;rison acc&#233;l&#233;r&#233;e&quot;&gt;gu&#233;rison acc&#233;l&#233;r&#233;e&lt;/a&gt; passe &#224; 10 et marche aussi quand il se trouve dans une zone de lumi&#232;re normale, en plus de fonctionner sous une vive lumi&#232;re. Le brasseur d’&#233;pines doit faire la d&#233;couverte &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;couvertes.html#GRANDMUTAGENE&quot; title=&quot;Les d&#233;couvertes d&amp;#39;alchimiste&quot;&gt;grand mutag&#232;ne&lt;/a&gt; avant de faire celle-ci.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;D&#233;couvertes conseill&#233;es&lt;a class=&quot;headeranchor&quot; id=&quot;D&#233;couvertes_conseill&#233;es_3&quot; href=&quot;#D&#233;couvertes_conseill&#233;es_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Voici les d&#233;couvertes qui viennent compl&#233;ter l’arch&#233;type de brasseur d’&#233;pines : &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;couvertes.html#BOMBEDEPRECISION&quot; title=&quot;Les d&#233;couvertes d&amp;#39;alchimiste&quot;&gt;bombe de pr&#233;cision&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;couvertes.html#BOMBEDEFOLIANTE&quot; title=&quot;Les d&#233;couvertes d&amp;#39;alchimiste&quot;&gt;bombe d&#233;foliante&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;couvertes.html#RETARDERLEDEPART&quot; title=&quot;Les d&#233;couvertes d&amp;#39;alchimiste&quot;&gt;retarder le d&#233;part&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;couvertes.html#BOMBEMITRAILLEUSE&quot; title=&quot;Les d&#233;couvertes d&amp;#39;alchimiste&quot;&gt;bombe mitrailleuse&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;couvertes.html#BOMBESOLEIL&quot; title=&quot;Les d&#233;couvertes d&amp;#39;alchimiste&quot;&gt;bombe soleil&lt;/a&gt;.
